// Asinh (BJS FlowGraphAsinhBlock, glTF op `math/asinh`).
// Data block (PULL): emits `value` via fg-math's `fgAsinh`.

import type { FgBlockDef } from "../../block-def.js";
import { FgBlockType } from "../../block-type.js";
import { FgType } from "../../types.js";
import { getDataValue, setDataValue } from "../../runtime.js";
import { sockIn, sockOut } from "../../sockets.js";
import { fgAsinh } from "../../fg-math.js";

export const asinhDef: FgBlockDef = {
    type: FgBlockType.Asinh,
    build: () => ({
        dataIn: [sockIn("a", FgType.Any)],
        dataOut: [sockOut("value", FgType.Any)],
    }),
    updateOutputs(block, ctx, env) {
        const a = getDataValue(ctx, env, block, "a");
        setDataValue(ctx, block, "value", fgAsinh(a));
    },
};
